const item = $input.item.json;

function findJsonText(node) {
  if (typeof node === 'string') {
    return node.includes('{') && node.includes('vendor') ? node : null;
  }
  if (Array.isArray(node)) {
    for (const el of node) { const r = findJsonText(el); if (r) return r; }
  } else if (node && typeof node === 'object') {
    for (const key of Object.keys(node)) { const r = findJsonText(node[key]); if (r) return r; }
  }
  return null;
}

const raw = findJsonText(item) || '';
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const clean = start !== -1 && end !== -1 ? raw.slice(start, end + 1) : '';

let data;
try { data = JSON.parse(clean); data.parse_ok = true; }
catch (e) { data = { parse_ok: false }; }

const tg = $('Telegram Trigger').item.json.message;
const media = tg.photo ? tg.photo[tg.photo.length - 1] : (tg.voice || tg.document || {});
const source = tg.photo ? 'photo' : tg.voice ? 'voice' : tg.document ? 'document' : 'text';

// Link to the receipt image saved in Drive (only exists for photos)
let file_link = '';
try { file_link = $('Upload receipt to Drive').first().json.webViewLink || ''; } catch (e) {}

return {
  json: {
    ...data,
    chat_id: tg.chat.id,
    telegram_file_id: media.file_id || null,
    source,
    file_link,
    status: data.parse_ok ? 'extracted' : 'failed',
    raw_debug: raw.slice(0, 300)
  }
};

const d = $('Merge category').first().json;
const rows = $('Get row(s) in sheet').all().map(r => r.json);

const issues = [];
if (!d.parse_ok) issues.push('تعذر قراءة الإيصال');
if (d.amount == null) issues.push('المبلغ غير واضح');
if (!d.vendor) issues.push('اسم المحل غير واضح');
if (!d.date) issues.push('التاريخ غير واضح');
if (typeof d.confidence === 'number' && d.confidence < 0.75) issues.push('ثقة القراءة منخفضة');
if (typeof d.amount === 'number' && d.amount > 50000) issues.push('مبلغ كبير بشكل غير معتاد');

const isDuplicate = rows.some(r =>
  r.vendor && String(r.vendor) === String(d.vendor) &&
  Number(r.amount) === Number(d.amount) &&
  String(r.date) === String(d.date)
);
if (isDuplicate) issues.push('يبدو أن هذا الإيصال مسجل من قبل');

return [{
  json: {
    ...d,
    needs_review: issues.length > 0,
    issues_text: issues.join(' • ')
  }
}];

const base = $('Parse JSON').first().json;
const context = $input.all()
  .map((i, n) => `${n + 1}. ${i.json.document?.pageContent ?? i.json.pageContent ?? ''}`)
  .join('\n');
return [{ json: { ...base, rag_context: context } }];

const base = $('Build context').first().json;

function findText(node) {
  if (typeof node === 'string') return node.includes('"category"') ? node : null;
  if (Array.isArray(node)) { for (const e of node) { const r = findText(e); if (r) return r; } }
  else if (node && typeof node === 'object') { for (const k of Object.keys(node)) { const r = findText(node[k]); if (r) return r; } }
  return null;
}

const raw = findText($input.first().json) || '';
let out = {};
try { out = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) {}

const allowed = ['rent','utilities','inventory','salaries','transport','food','marketing','maintenance','taxes','other'];
const ok = allowed.includes(out.category);

return [{ json: {
  ...base,
  category: ok ? out.category : (base.category || 'other'),
  category_reason: out.reason || '',
  category_source: ok ? 'rag' : 'fallback'
}}];

