const DAYS = 7; // testing: includes all old rows. Change to 7 for the real weekly report.

const rows = $input.all().map(r => r.json);
const now = new Date();
const from = new Date(now.getTime() - DAYS * 24 * 3600 * 1000);

const recent = rows.filter(r => {
  const d = new Date(r.date);
  return !isNaN(d) && d >= from && d <= now && r.status !== 'failed';
});

const egp = recent.filter(r => (r.currency || 'EGP') === 'EGP');
const total = egp.reduce((s, r) => s + (Number(r.amount) || 0), 0);

const byCat = {};
egp.forEach(r => {
  const c = r.category || 'other';
  byCat[c] = (byCat[c] || 0) + (Number(r.amount) || 0);
});
const cats = Object.entries(byCat).sort((a, b) => b[1] - a[1]);

const confirmed = recent.filter(r => r.status === 'confirmed_by_user').length;
const otherCurrency = recent.length - egp.length;

const stats_text =
`Period: last ${DAYS} days
Expenses recorded: ${recent.length} (in EGP: ${egp.length}, other currencies: ${otherCurrency})
Total EGP: ${total.toFixed(2)}
By category (EGP): ${cats.map(([c, v]) => c + ' ' + v.toFixed(2)).join(', ') || 'none'}
Needed manual confirmation: ${confirmed}`;

return [{ json: { stats_text, total, count: recent.length } }];

const rows = $input.all().map(r => r.json).filter(r => r.status !== 'failed' && r.amount);
const q = $('Telegram Trigger').first().json.message;

const lines = rows.slice(-150).map(r =>
  `${r.date} | ${r.vendor || '-'} | ${r.description || '-'} | ${r.amount} ${r.currency || 'EGP'} | ${r.category || 'other'}`
).join('\n');

return [{ json: {
  question: q.text,
  chat_id: q.chat.id,
  today: new Date().toISOString().slice(0, 10),
  ledger_text: `ENTRIES (date | vendor | description | amount currency | category):\n${lines}`
}}];

const chat_id = $('Telegram Trigger').first().json.message.chat.id;
const rows = $input.all().map(r => r.json).filter(r => r.row_number);
if (!rows.length) return [{ json: { found: false, chat_id } }];
const last = rows[rows.length - 1];
return [{ json: {
  found: true,
  chat_id,
  row_number: last.row_number,
  summary: `${last.vendor || '-'} | ${last.amount} ${last.currency || ''} | ${last.category || ''}`
}}];

const text = ($json.message?.text || '').trim();

// Turn Arabic-Indic digits into normal digits so the number check works
const normalized = text.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const hasNumber = /\d/.test(normalized);

const isQuestion =
  /[؟?]/.test(text) ||
  /^(كم|كام|بكام|ايه|إيه|ما|ماذا|متى|امتى|ازاي)(\s|$)/.test(text) ||
  /^(how|what|when|which|show|list)\b/i.test(text);

let intent = 'other';
if (isQuestion) intent = 'question';
else if (hasNumber) intent = 'expense';

return { json: { intent, text } };
